program.source:
Funcion word <- HowItWent(codigo Como Entero)
  Definir word Como Cadena;
  Si codigo = 200 Entonces
    word <- "fine";
  Sino
    word <- "problem";
  FinSi
FinFuncion

Algoritmo Estado
  Definir codigo Como Entero;
  Leer codigo;
  Escribir HowItWent(codigo);
FinAlgoritmo

